--- a/wolfmqtt/src/mqtt_client.c
+++ b/wolfmqtt/src/mqtt_client.c
@@ -1823,6 +1823,12 @@
 #ifdef WOLFMQTT_V5
     /* Use specified protocol version if set */
     unsubscribe->protocol_level = client->protocol_level;
+
+    /* Ensure ack properties are in a known state for this transaction.
+     * This avoids freeing stale/uninitialized pointers on error or malformed
+     * UNSUBACK decode paths.
+     */
+    unsubscribe->ack.props = NULL;
 #endif

     if (unsubscribe->stat == MQTT_MSG_BEGIN) {
@@ -1903,6 +1909,7 @@
     if (unsubscribe->ack.props != NULL) {
         /* Release the allocated properties */
         MqttClient_PropsFree(unsubscribe->ack.props);
+        unsubscribe->ack.props = NULL;
     }
 #endif

